CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT 'Student', college text NOT NULL DEFAULT 'NIET College', location text NOT NULL DEFAULT 'Greater Noida', language text NOT NULL DEFAULT 'Hindi + English', teaches text[] NOT NULL DEFAULT '{}', learns text[] NOT NULL DEFAULT '{}', availability text[] NOT NULL DEFAULT '{Sat}', bio text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO anon, authenticated; GRANT INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public student profiles" ON public.profiles FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Own profile insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id=auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_student_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES (NEW.id,coalesce(nullif(NEW.raw_user_meta_data->>'name',''),nullif(NEW.raw_user_meta_data->>'full_name',''),'Student')); RETURN NEW; END; $$;
CREATE TRIGGER create_student_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_student_profile();
CREATE TABLE public.exchange_skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mentor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', tags text[] NOT NULL DEFAULT '{}', level text NOT NULL DEFAULT 'Beginner' CHECK(level IN ('Beginner','Intermediate','Advanced')), availability text[] NOT NULL DEFAULT '{Sat}', mode text NOT NULL DEFAULT 'Online' CHECK(mode IN ('Online','In person')));
GRANT SELECT ON public.exchange_skills TO anon,authenticated; GRANT INSERT, UPDATE, DELETE ON public.exchange_skills TO authenticated; GRANT ALL ON public.exchange_skills TO service_role;
ALTER TABLE public.exchange_skills ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Browse skills" ON public.exchange_skills FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Own skills" ON public.exchange_skills FOR ALL TO authenticated USING(mentor_id=auth.uid()) WITH CHECK(mentor_id=auth.uid());
CREATE TABLE public.learning_wants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, topic text NOT NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.learning_wants TO authenticated; GRANT ALL ON public.learning_wants TO service_role;
ALTER TABLE public.learning_wants ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own learning goals" ON public.learning_wants FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.exchange_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), learner_id uuid NOT NULL REFERENCES public.profiles(id), mentor_id uuid NOT NULL REFERENCES public.profiles(id), skill_id uuid NOT NULL REFERENCES public.exchange_skills(id), date date NOT NULL, time text NOT NULL CHECK(time IN ('09:00','11:00','14:00','16:00','18:00','20:00')), note text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','completed','cancelled')), payment text NOT NULL DEFAULT 'swap' CHECK(payment IN ('swap','credits')), proof text NOT NULL DEFAULT '', proof_path text NOT NULL DEFAULT '', feedback text NOT NULL DEFAULT '', rating integer CHECK(rating BETWEEN 1 AND 5), created_at timestamptz NOT NULL DEFAULT now(), CHECK(learner_id<>mentor_id));
GRANT SELECT ON public.exchange_sessions TO authenticated; GRANT ALL ON public.exchange_sessions TO service_role;
ALTER TABLE public.exchange_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants read sessions" ON public.exchange_sessions FOR SELECT TO authenticated USING(auth.uid() IN(learner_id,mentor_id));
CREATE TABLE public.credit_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), session_id uuid REFERENCES public.exchange_sessions(id), amount integer NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,session_id,reason));
GRANT SELECT ON public.credit_ledger TO authenticated; GRANT ALL ON public.credit_ledger TO service_role;
ALTER TABLE public.credit_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own wallet" ON public.credit_ledger FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.book_exchange(p_skill uuid,p_date date,p_time text,p_note text,p_payment text DEFAULT 'swap') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.exchange_skills; r uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT * INTO s FROM public.exchange_skills WHERE id=p_skill; IF NOT FOUND OR s.mentor_id=auth.uid() THEN RAISE EXCEPTION 'Choose another student'; END IF; IF p_date<current_date OR NOT (trim(to_char(p_date,'Dy'))=ANY(s.availability)) THEN RAISE EXCEPTION 'Choose an available future date'; END IF; PERFORM pg_advisory_xact_lock(hashtext(s.mentor_id::text||p_date::text||p_time)); IF EXISTS(SELECT 1 FROM public.exchange_sessions WHERE mentor_id=s.mentor_id AND date=p_date AND time=p_time AND status IN('pending','accepted')) THEN RAISE EXCEPTION 'This slot is already reserved'; END IF; IF p_payment='credits' THEN PERFORM 1 FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF coalesce((SELECT sum(amount) FROM public.credit_ledger WHERE user_id=auth.uid()),0)<1 THEN RAISE EXCEPTION 'Earn a credit by teaching first, or choose a skill swap'; END IF; END IF; INSERT INTO public.exchange_sessions(learner_id,mentor_id,skill_id,date,time,note,payment) VALUES(auth.uid(),s.mentor_id,p_skill,p_date,p_time,left(p_note,2000),p_payment) RETURNING id INTO r; IF p_payment='credits' THEN INSERT INTO public.credit_ledger(user_id,session_id,amount,reason) VALUES(auth.uid(),r,-1,'Session reservation'); END IF; RETURN r; END; $$;
CREATE FUNCTION public.respond_exchange(p_id uuid,p_status text,p_feedback text DEFAULT '',p_rating integer DEFAULT 5) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.exchange_sessions; BEGIN SELECT * INTO s FROM public.exchange_sessions WHERE id=p_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Session not found'; END IF; IF p_status='cancelled' THEN IF auth.uid() NOT IN(s.mentor_id,s.learner_id) OR s.status NOT IN('pending','accepted') THEN RAISE EXCEPTION 'Cannot cancel'; END IF; ELSIF auth.uid()<>s.mentor_id THEN RAISE EXCEPTION 'Only the mentor can respond'; ELSIF p_status IN('accepted','declined') AND s.status<>'pending' THEN RAISE EXCEPTION 'Already responded'; ELSIF p_status='completed' AND (s.status<>'accepted' OR length(s.proof)<5 OR length(trim(p_feedback))<5 OR s.date>current_date) THEN RAISE EXCEPTION 'Complete the session and add learning proof and feedback first'; ELSIF p_status NOT IN('accepted','declined','completed') THEN RAISE EXCEPTION 'Invalid action'; END IF; UPDATE public.exchange_sessions SET status=p_status,feedback=CASE WHEN p_status='completed' THEN left(p_feedback,2000) ELSE feedback END,rating=CASE WHEN p_status='completed' THEN p_rating ELSE rating END WHERE id=p_id; IF p_status IN('cancelled','declined') AND s.payment='credits' THEN INSERT INTO public.credit_ledger(user_id,session_id,amount,reason) VALUES(s.learner_id,p_id,1,'Reservation refund'); END IF; IF p_status='completed' THEN INSERT INTO public.credit_ledger(user_id,session_id,amount,reason) VALUES(s.mentor_id,p_id,1,'Teaching completed'); END IF; END; $$;
CREATE FUNCTION public.submit_learning_proof(p_id uuid,p_proof text,p_path text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(trim(p_proof))<5 OR length(p_proof)>2000 THEN RAISE EXCEPTION 'Add a short learning reflection'; END IF; IF p_path<>'' AND split_part(p_path,'/',1)<>auth.uid()::text THEN RAISE EXCEPTION 'Invalid file'; END IF; UPDATE public.exchange_sessions SET proof=p_proof,proof_path=p_path WHERE id=p_id AND learner_id=auth.uid() AND status='accepted'; IF NOT FOUND THEN RAISE EXCEPTION 'Only the learner can submit proof for a confirmed session'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.book_exchange(uuid,date,text,text,text), public.respond_exchange(uuid,text,text,integer), public.submit_learning_proof(uuid,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.book_exchange(uuid,date,text,text,text), public.respond_exchange(uuid,text,text,integer), public.submit_learning_proof(uuid,text,text) TO authenticated;
CREATE INDEX sessions_learner_idx ON public.exchange_sessions(learner_id); CREATE INDEX sessions_mentor_idx ON public.exchange_sessions(mentor_id); CREATE INDEX ledger_user_idx ON public.credit_ledger(user_id);
CREATE POLICY "Upload own learning files" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='learning-proof' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Read participant learning files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='learning-proof' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.exchange_sessions WHERE proof_path=name AND mentor_id=auth.uid())));